import { useState } from 'react';

const produk = [
  { id: 1, nama: 'Kopi Susu', promo: true },
  { id: 2, nama: 'Kopi Aren', promo: false },
  { id: 3, nama: 'Teh Melati', promo: true },
];

export default function App() {
  const [kata, setKata] = useState('');
  const [hanyaPromo, setHanyaPromo] = useState(false);

  const hasil = produk
    .filter((p) => p.nama.toLowerCase().includes(kata.toLowerCase()))
    .filter((p) => !hanyaPromo || p.promo);

  function handleBeli(p) {
    console.log(`${p.nama} dibeli`);
  }

  return (
    <div>
      <input value={kata} onChange={(e) => setKata(e.target.value)} placeholder="Cari" />{' '}
      <label>
        <input type="checkbox" checked={hanyaPromo} onChange={(e) => setHanyaPromo(e.target.checked)} /> Hanya promo
      </label>
      <ul>
        {hasil.map((p) => (
          <li key={p.id}>
            {p.nama} <button onClick={() => handleBeli(p)}>Beli</button>
          </li>
        ))}
      </ul>
      <small>{hasil.length} produk</small>
    </div>
  );
}
